#!/bin/bash
#
###############################################################################
# Script to configure and enable Mirroring 
# maintainer: 
# 
#
# USAGE
#   - Copy script files to ASIK (for example to /ffs/run/config/scripts/ folder)
#       - 
#   - Give execution rights 
#       chmod +x /ffs/run/config/scripts/*.sh
#   - Run script
#       sh /ffs/run/config/scripts/
#   - capture is stored to /tmp/tcpdump_L2L1_bip[_filtering_[off|on].pcap000
#   - Remember to delete captures from ASIB after downloading to not to break SW upgrade due to insufficient disk space

VERSION_STRING='V01'

YELLOW='\e[33m'
RED='\e[31m'
GREEN='\e[32m'
NC='\e[0m'

bip_script_dict=([ASIB]="ethsei02" [ASIL]="sei11")
directory="$( cd "$( dirname "${BASH_SOURCE[0]}" )" >/dev/null 2>&1 && pwd )"


readOptionsFromComonFile() {
    source $directory/common_funcs.sh
    if [ $? -eq 0 ]; then 
        echo -e "\n${YELLOW}Read options from common_funcs.sh${NC}"
    else 
        echo -e "\n${RED}Config file (common_funcs.sh) not found${NC}"
        exit
    fi
}

echo -e "\n${YELLOW}bip_asbi_abio.sh $VERSION_STRING${NC}"
readOptionsFromComonFile



checkSwReleaseAndHW

if [ "${L1bypass}" == "FS" ]; then
    echo "fullstack TL execute gnbMirroring.sh"
    sh gnbMirroring.sh "$@"
else
  if [ "${bb_board_type_list[0]}" == "ABIO" ]; then
      echo "ABIO TL execute bip_abio.sh"
      sh bip_abio.sh "$@"
  fi
  if [[ $controlCardHwType == 'ASIB' ]] && [[ "${bb_board_type_list[0]}" == "ABIL" ]]; then
      echo "ABIL TL execute bip_asib_abil.sh"
      sh bip_asib_abil.sh "$@"
  fi

fi